"use strict";(globalThis.webpackChunkgrc||=[]).push([[77177],{39932(e){e.exports=JSON.parse('{"citeKey":"kougkas2019labios","slug":"kougkas-2019-labios-8411","title":"LABIOS: A Distributed Label-Based I/O System","authors":["A. Kougkas","H. Devarajan","J. Lofstead","X.-H. Sun"],"venue":"The 28th International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'19), Phoenix, USA 2019. pp. 13-24. Karsten Schwan Best Paper Award","type":"Conference","entryType":"inproceedings","date":"June, 2019","year":2019,"era":"iit","month":6,"doi":"10.1145/3307681.3325405","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting re- quirements. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elastic- ity, and promotes in-situ analytics via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411.pdf","slides":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411-slides.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage","Hermes"],"_projectIds":["hermes","labios","iris","direcmr","ides","integrated-data-mgmt"],"grcSelected":false,"grcAwards":"Karsten Schwan Best Paper Award","status":"published","visibility":"public","projectIds":["labios","dtio","hermes","iris","ides","direcmr","integrated-data-mgmt"],"memberAuthors":["kougkas-anthony","devarajan-hariharan","lofstead-jay","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"},{"agency":"NSF","award":"CCF-1744317","projectId":"direcmr"},{"agency":"NSF","award":"CNS-1730488","projectId":"ides"},{"agency":"NSF","award":"CNS-1526887","projectId":"integrated-data-mgmt"}]}')}}]);